Auth::requireRole(['super_admin','owner']);
$pageTitle='Upload Excel Stock Opname';$db=Database::connect();opname_ensure_tables($db);
function opname_import_header(string $value):string{$value=trim(strtolower($value));$value=preg_replace('/^\xEF\xBB\xBF/','',$value);$value=str_replace([' ','-','.','/','\\'],'_',$value);return trim((string)preg_replace('/[^a-z0-9_]/','',$value),'_');}
if(is_post())try{
 if(!CSRF::verify())throw new Exception('Token keamanan tidak valid.');$file=$_FILES['opname_file']??[];if(empty($file['tmp_name'])||($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new Exception('Pilih file Excel .xlsx terlebih dahulu.');if(strtolower(pathinfo((string)($file['name']??''),PATHINFO_EXTENSION))!=='xlsx')throw new Exception('Format file harus XLSX.');if((int)($file['size']??0)>10*1024*1024)throw new Exception('Ukuran file maksimal 10 MB.');
 $matrix=KpXlsx::readFirstSheet($file['tmp_name'],5005);if(!$matrix)throw new Exception('File Excel kosong atau tidak terbaca.');$headerIndex=null;$headers=[];foreach(array_slice($matrix,0,12,true) as $i=>$candidate){$norm=array_map('opname_import_header',(array)$candidate);if(in_array('name',$norm,true)&&in_array('physical_stock',$norm,true)){$headerIndex=(int)$i;$headers=$norm;break;}}if($headerIndex===null)throw new Exception('Header name dan physical_stock tidak ditemukan. Gunakan template terbaru.');$map=array_flip($headers);$parsed=[];
 foreach(array_slice($matrix,$headerIndex+1) as $offset=>$row){$name=trim((string)($row[$map['name']]??''));if($name==='')continue;$raw=trim((string)($row[$map['physical_stock']]??''));$physical=$raw===''?null:(int)preg_replace('/[^0-9\-]/','',$raw);if($physical!==null&&$physical<0)throw new Exception('Stok fisik tidak boleh minus pada baris '.($headerIndex+$offset+2));$parsed[]=['name'=>$name,'variant'=>isset($map['variant'])?trim((string)($row[$map['variant']]??'')):'','product_id'=>isset($map['product_id'])?(int)($row[$map['product_id']]??0):0,'variant_id'=>isset($map['variant_id'])?(int)($row[$map['variant_id']]??0):0,'physical'=>$physical,'note'=>isset($map['note'])?trim((string)($row[$map['note']]??'')):''];}
 if(!$parsed)throw new Exception('Tidak ada data produk yang bisa diimpor.');$title=trim((string)($_POST['title']??''))?:('Opname Excel '.date('d/m/Y H:i'));$sessionNote=trim((string)($_POST['note']??''));$branchId=branch_current_id($db);
 $db->beginTransaction();$code=opname_code($db);$stmt=$db->prepare("INSERT INTO stock_opnames(code,title,user_id,branch_id,status,note,created_at) VALUES(?,?,?,?,'draft',?,NOW())");$stmt->execute([$code,$title,Auth::id(),$branchId,$sessionNote]);$opnameId=(int)$db->lastInsertId();
 $findProduct=$db->prepare('SELECT id,name,product_code,unit,stock,purchase_price,selling_price FROM products WHERE id=? AND is_active=1 LIMIT 1');$findByName=$db->prepare('SELECT id,name,product_code,unit,stock,purchase_price,selling_price FROM products WHERE is_active=1 AND LOWER(TRIM(name))=LOWER(TRIM(?)) ORDER BY id LIMIT 2');$findVariant=$db->prepare('SELECT * FROM marketplace_product_variants WHERE id=? AND product_id=? LIMIT 1');$findVariantName=$db->prepare('SELECT * FROM marketplace_product_variants WHERE product_id=? AND LOWER(TRIM(name))=LOWER(TRIM(?)) ORDER BY id LIMIT 2');
 $insert=$db->prepare('INSERT INTO stock_opname_items(opname_id,product_id,variant_id,product_name,variant_name,product_code,unit,system_stock,physical_stock,difference,purchase_price,selling_price,difference_value,reason,note,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW())');$matched=0;$unmatched=[];$duplicates=[];
 foreach($parsed as $row){$p=null;if($row['product_id']>0){$findProduct->execute([$row['product_id']]);$p=$findProduct->fetch()?:null;}else{$baseName=$row['name'];if($row['variant']!==''&&str_ends_with(mb_strtolower($baseName),mb_strtolower(' - '.$row['variant'])))$baseName=mb_substr($baseName,0,mb_strlen($baseName)-mb_strlen(' - '.$row['variant']));$findByName->execute([$baseName]);$found=$findByName->fetchAll();if(count($found)>1){$duplicates[]=$row['name'];continue;}$p=$found[0]??null;}if(!$p){$unmatched[]=$row['name'];continue;}
  $variant=null;$variantId=max(0,(int)$row['variant_id']);if($variantId>0){$findVariant->execute([$variantId,$p['id']]);$variant=$findVariant->fetch()?:null;}elseif($row['variant']!==''){$findVariantName->execute([$p['id'],$row['variant']]);$vrows=$findVariantName->fetchAll();if(count($vrows)>1){$duplicates[]=$row['name'];continue;}$variant=$vrows[0]??null;$variantId=(int)($variant['id']??0);}if($row['variant']!==''&&!$variant){$unmatched[]=$row['name'];continue;}
  if($variant){$vlabel=marketplace_v159_variant_label($db,$variantId,(string)$variant['name']);$system=marketplace_v16_variant_stock($db,$variantId,$branchId,false);$purchase=(float)($variant['purchase_price']?:$p['purchase_price']);$selling=(float)($variant['selling_price']?:$p['selling_price']);$codeOut=$variant['sku']?:$p['product_code'];$display=$p['name'].' - '.$vlabel;}else{$vlabel=null;$system=(int)$p['stock'];try{$q=$db->prepare('SELECT stock FROM product_branch_stocks WHERE branch_id=? AND product_id=?');$q->execute([$branchId,$p['id']]);$x=$q->fetchColumn();if($x!==false)$system=(int)$x;}catch(Throwable $e){}$purchase=(float)$p['purchase_price'];$selling=(float)$p['selling_price'];$codeOut=$p['product_code'];$display=$p['name'];}
  $physical=$row['physical'];$diff=$physical===null?0:$physical-$system;$reason=$physical===null?null:($diff===0?'match':($diff>0?'found':'missing'));$insert->execute([$opnameId,$p['id'],$variantId,$display,$vlabel,$codeOut,$p['unit'],$system,$physical,$diff,$purchase,$selling,abs($diff)*$purchase,$reason,$row['note']]);$matched++;}
 if($matched<1)throw new Exception('Tidak ada produk/varian Excel yang cocok dengan database.');opname_sync_totals($db,$opnameId);$db->commit();Auth::log('import_stock_opname',"Import Excel stock opname {$code}: {$matched} baris");$msg="Excel berhasil diimpor: {$matched} produk/varian masuk draft opname.";if($unmatched)$msg.=' Tidak ditemukan: '.count($unmatched).'.';if($duplicates)$msg.=' Data ambigu: '.count($duplicates).'.';flash('success',$msg);legacy_redirect('admin/stock-opname/edit.php?id='.$opnameId);
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('error','Import opname gagal: '.$e->getMessage());legacy_redirect('admin/stock-opname/import.php');}
